CREATE TABLE workflows(id BIGSERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,description TEXT,status VARCHAR(30) NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);CREATE TABLE workflow_steps(id BIGSERIAL PRIMARY KEY,workflow_id BIGINT NOT NULL REFERENCES workflows(id),name VARCHAR(200) NOT NULL,description TEXT,position INT NOT NULL,requires_approval BOOLEAN NOT NULL DEFAULT false,success_next_step_id BIGINT,failure_next_step_id BIGINT);ALTER TABLE workflow_steps ADD CONSTRAINT fk_step_success FOREIGN KEY(success_next_step_id) REFERENCES workflow_steps(id);ALTER TABLE workflow_steps ADD CONSTRAINT fk_step_failure FOREIGN KEY(failure_next_step_id) REFERENCES workflow_steps(id);CREATE TABLE command_steps(id BIGINT PRIMARY KEY REFERENCES workflow_steps(id),command_definition_id BIGINT REFERENCES command_definitions(id),command_template TEXT NOT NULL,parameters JSONB,run_with_sudo BOOLEAN NOT NULL DEFAULT false,timeout_seconds INT NOT NULL DEFAULT 60);CREATE TABLE file_transfer_steps(id BIGINT PRIMARY KEY REFERENCES workflow_steps(id),stored_file_id BIGINT NOT NULL,destination_path TEXT NOT NULL,overwrite BOOLEAN NOT NULL DEFAULT false,timeout_seconds INT NOT NULL DEFAULT 120);CREATE TABLE wait_until_steps(id BIGINT PRIMARY KEY REFERENCES workflow_steps(id),check_type VARCHAR(50) NOT NULL,check_command TEXT,expected_output TEXT,check_interval_seconds INT NOT NULL DEFAULT 5,timeout_seconds INT NOT NULL DEFAULT 120);ALTER TABLE executions ADD CONSTRAINT fk_execution_workflow FOREIGN KEY(workflow_id) REFERENCES workflows(id);ALTER TABLE step_runs ADD CONSTRAINT fk_step_run_workflow_step FOREIGN KEY(workflow_step_id) REFERENCES workflow_steps(id);